   val nodes=graph.getJSONObject("nodes");val keys=nodes.keys().asSequence().toList();keys.forEach{id->val node=nodes.getJSONObject(id);TextButton(onClick={nodeID=id;page=0}){Text("${node.getString("kind")} · ${node.getString("label")} · ${node.getString("status")}")}}
   (nodeID.takeIf{nodes.has(it)} ?: keys.firstOrNull())?.let{id->val node=nodes.getJSONObject(id);Text(node.getString("path"),fontSize=12.sp);Text("${node.getString("status")} · captured hash ${node.opt("hash")}",fontSize=12.sp);val preview=if(node.isNull("preview"))"Readable captured preview unavailable; missing content is not inferred." else node.getString("preview");val count=((preview.length+7999)/8000).coerceAtLeast(1);val current=page.coerceIn(0,count-1);Text(preview.substring(current*8000,((current+1)*8000).coerceAtMost(preview.length)),fontSize=12.sp);Text("Captured previews may be abbreviated by the provider.",fontSize=12.sp);Row{WithDisabledReason(if (current <= 0) "You’re on the first page." else null) { available -> TextButton(enabled = available,onClick={page=current-1}){Text("Previous preview")} };WithDisabledReason(if (current >= count-1) "You’re on the last page." else null) { available -> TextButton(enabled = available,onClick={page=current+1}){Text("Next preview")} }}
    val path=if(node.isNull("source_path"))node.getString("path") else node.getString("source_path");TextButton(onClick={scope.launch{m.openCurrentSource(w,path)}}){Text("Open current readable source · ${JSONObject.quote(path)}")}
